record.field:
name = (arguments.get('customer_name') or '').strip()
partner = env['res.partner'].search([('name', 'ilike', name)], limit=1) if name else env['res.partner'].browse()
if not partner:
    result['output'] = 'No customer found matching "%s".' % name
else:
    result['output'] = 'Customer %s has an outstanding receivable balance of %.2f.' % (partner.name, partner.credit or 0.0)
